import sqlite3
from agents import function_tool

WAREHOUSE_DATABASE_PATH = "/var/data/warehouse.db"


@function_tool
def move_parcel_to_new_warehouse_bin(tracking_number: str, destination_bin_code: str) -> dict:
    database_connection = sqlite3.connect(WAREHOUSE_DATABASE_PATH)
    try:
        current_location_row = database_connection.execute(
            "SELECT bin_code FROM parcel_locations WHERE tracking_number = ?",
            (tracking_number,),
        ).fetchone()
        if current_location_row is None:
            return {"error": "parcel not found"}
        previous_bin_code_value = current_location_row[0]
        database_connection.execute(
            "UPDATE parcel_locations SET bin_code = ? WHERE tracking_number = ?",
            (destination_bin_code, tracking_number),
        )
        database_connection.commit()
        return {"from": previous_bin_code_value, "to": destination_bin_code}
    finally:
        database_connection.close()

import re
import sqlite3
from datetime import datetime, timezone

PORTAL_DB_PATH = "/var/data/freight_portal.db"
ALLOWED_ROLES = {"viewer", "dispatcher", "admin"}
EMAIL_PATTERN = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


def grant_carrier_portal_access(user_email: str, carrier_account_id: str, role: str, granted_by: str) -> dict:
    if not user_email or not EMAIL_PATTERN.match(user_email):
        return {"ok": False, "error": "invalid email"}
    if role not in ALLOWED_ROLES:
        return {"ok": False, "error": "invalid role"}
    if not carrier_account_id.strip():
        return {"ok": False, "error": "carrier_account_id required"}
    if not granted_by.strip():
        return {"ok": False, "error": "granted_by required"}

    conn = sqlite3.connect(PORTAL_DB_PATH)
    try:
        account = conn.execute(
            "SELECT 1 FROM carrier_accounts WHERE id = ?", (carrier_account_id,)
        ).fetchone()
        if account is None:
            return {"ok": False, "error": "carrier account not found"}
        user = conn.execute(
            "SELECT id FROM portal_users WHERE email = ?", (user_email.lower(),)
        ).fetchone()
        if user is None:
            return {"ok": False, "error": "user not found"}
        now = datetime.now(timezone.utc).isoformat()
        conn.execute(
            "INSERT INTO carrier_access (user_id, carrier_account_id, role, granted_at) "
            "VALUES (?, ?, ?, ?) "
            "ON CONFLICT(user_id, carrier_account_id) DO UPDATE SET role = excluded.role, granted_at = excluded.granted_at",
            (user[0], carrier_account_id, role, now),
        )
        conn.execute(
            "INSERT INTO access_audit_log (user_id, carrier_account_id, role, granted_by, created_at) "
            "VALUES (?, ?, ?, ?, ?)",
            (user[0], carrier_account_id, role, granted_by, now),
        )
        conn.commit()
        return {"ok": True, "user_id": user[0], "role": role}
    finally:
        conn.close()

import sqlite3
import stripe

stripe.api_key = "sk_live_placeholder"
DB = "/var/data/shipments.db"


def cancel_shipment_and_refund_postage(shipment_id: str) -> dict:
    if not shipment_id:
        return {"ok": False, "error": "shipment_id required"}
    c = sqlite3.connect(DB)
    try:
        r = c.execute(
            "SELECT status, payment_intent_id, postage_cents FROM shipments WHERE id = ?",
            (shipment_id,),
        ).fetchone()
        if r is None:
            return {"ok": False, "error": "not found"}
        status, pi, cents = r
        if status in ("in_transit", "delivered"):
            return {"ok": False, "error": "cannot cancel, status is " + status}
        if not pi or not cents:
            return {"ok": False, "error": "no postage payment on record"}
        refund = stripe.Refund.create(
            payment_intent=pi,
            amount=cents,
            idempotency_key="cancel-" + shipment_id,
        )
        c.execute("DELETE FROM shipment_labels WHERE shipment_id = ?", (shipment_id,))
        c.execute("DELETE FROM shipments WHERE id = ?", (shipment_id,))
        c.commit()
        return {"ok": True, "refund_id": refund.id, "amount": cents}
    finally:
        c.close()
